mapper.update:
UPDATE jq_todos_subtask
SET deleted = 1,
    updater = #{updater},
    update_time = NOW()
WHERE parent_id = #{parentId}
  AND (deleted = 0 OR deleted IS NULL)
  AND id NOT IN (
      SELECT id FROM (
          SELECT id FROM jq_todos_subtask
          WHERE parent_id = #{parentId}
            AND (deleted = 0 OR deleted IS NULL)
          ORDER BY id
          LIMIT #{keepCount}
      ) AS keep_ids
  )

mapper.select:
SELECT 
FROM jq_todos_subtask
WHERE parent_id = #{parentId}
  AND asignee_id = #{asigneeOaId}
  AND (deleted = 0 OR deleted IS NULL)
LIMIT 1
